     4→using System;
     5→using Nethermind.Core.Attributes;
     6→using Nethermind.Core.Crypto;
     7→
     8→namespace Nethermind.Core
     9→{
    10→    public class TxReceipt
    11→    {
    12→        private Bloom? _boom;
    13→
    14→        public TxReceipt()
    15→        {
    16→        }
    17→
    18→        public TxReceipt(TxReceipt other)
    19→        {
    20→            TxType = other.TxType;
    21→            StatusCode = other.StatusCode;
    22→            BlockNumber = other.BlockNumber;
    23→            BlockHash = other.BlockHash;
    24→            TxHash = other.TxHash;
    25→            Index = other.Index;
    26→            GasUsed = other.GasUsed;
    27→            GasUsedTotal = other.GasUsedTotal;
    28→            Sender = other.Sender;
    29→            ContractAddress = other.ContractAddress;
    30→            Recipient = other.Recipient;
    31→            ReturnValue = other.ReturnValue;
    32→            PostTransactionState = other.PostTransactionState;
    33→            Bloom = other.Bloom;
    34→            Logs = other.Logs;
    35→            Error = other.Error;
    36→        }
    37→
    38→        /// <summary>
    39→        /// EIP-2718 transaction type
    40→        /// </summary>
    41→        public TxType TxType { get; set; }
    42→
    43→        /// <summary>
    44→        ///     EIP-658
    45→        /// </summary>
    46→        public byte StatusCode { get; set; }
    47→        public long BlockNumber { get; set; }
    48→        public Hash256? BlockHash { get; set; }
    49→        public Hash256? TxHash { get; set; }
    50→        public int Index { get; set; }
    51→        public long GasUsed { get; set; }
    52→        public long GasUsedTotal { get; set; }
    53→        public Address? Sender { get; set; }
    54→        public Address? ContractAddress { get; set; }
    55→        public Address? Recipient { get; set; }
    56→
    57→        [Todo(Improve.Refactor, "Receipt tracer?")]
    58→        public byte[]? ReturnValue { get; set; }
    59→
    60→        /// <summary>
    61→        ///     Removed in EIP-658
    62→        /// </summary>
    63→        public Hash256? PostTransactionState { get; set; }
    64→        public Bloom? Bloom { get => _boom ?? CalculateBloom(); set => _boom = value; }
    65→        public LogEntry[]? Logs { get; set; }
    66→        public string? Error { get; set; }
